import * as THREE from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, float, vec3, uniform, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-stat-tile';
  group.position.set(-1.25, 0.7, 0);

  const imageUrl = '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = '/prism-mock/home/nodes/parallax-stack.depth.png';

  const colorMap = ctx.textureLoader.load(imageUrl);
  const depthMap = ctx.textureLoader.load(depthUrl);
  colorMap.colorSpace = THREE.SRGBColorSpace;

  const geometry = new THREE.PlaneGeometry(1.5, 0.9, 64, 64);

  const displacementAmount = uniform(0.08);
  const colorTex = texture(colorMap, uv());
  const depthTex = texture(depthMap, uv());

  const displaced = positionLocal.add(
    normalLocal.mul(depthTex.r.sub(0.5).mul(displacementAmount))
  );

  const material = new THREE.MeshPhysicalNodeMaterial({
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  material.colorNode = mix(vec3(0.086, 0.086, 0.114), colorTex.rgb, float(0.85));
  material.positionNode = displaced;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'stat-tile-surface';
  group.add(mesh);

  // edge frame (accent) — machined bezel
  const edgeGeo = new THREE.PlaneGeometry(1.56, 0.96);
  const edgeMat = new THREE.MeshBasicNodeMaterial({
    color: new THREE.Color('#ff2a38'),
    transparent: true,
    opacity: 0,
  });
  const edge = new THREE.Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.01;
  edge.name = 'stat-tile-accent-edge';
  group.add(edge);

  // value + label text via MSDF atlas
  let valueText = null;
  let labelText = null;
  try {
    valueText = ctx.fontAtlas.createText({
      text: config.textContent?.value || '—',
      font: 'text',
      weight: 700,
      size: 0.2,
      color: '#e8ecf2',
      anchor: 'center',
    });
    valueText.position.set(0, 0.15, 0.02);
    group.add(valueText);

    labelText = ctx.fontAtlas.createText({
      text: config.textContent?.label || 'Metric',
      font: 'text',
      weight: 400,
      size: 0.09,
      color: '#e8ecf2',
      anchor: 'center',
    });
    labelText.position.set(0, -0.15, 0.02);
    group.add(labelText);
  } catch (e) {
    // font atlas unavailable — skip text
  }

  // apply required cinematic primitive: parallax-scroll
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { trigger: 'scroll', intensity: 0.25 });
  }

  // interactions
  const baseY = group.position.y;
  let hoverTl = null;
  let pressTl = null;

  const onHoverIn = () => {
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' });
    hoverTl.to(edgeMat, { opacity: 0.6, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(mesh.scale, { x: 1.02, y: 1.02, duration: 0.7, ease: 'power3.out' }, 0);
  };

  const onHoverOut = () => {
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: baseY, duration: 0.5, ease: 'power2.out' });
    hoverTl.to(edgeMat, { opacity: 0, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(mesh.scale, { x: 1, y: 1, duration: 0.5, ease: 'power2.out' }, 0);
  };

  const onClick = () => {
    pressTl?.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    pressTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out' });
    if (ctx.emit) {
      ctx.emit('hub-features.select', { nodeId: group.name });
    }
  };

  group.userData.handlers = {
    onPointerOver: onHoverIn,
    onPointerOut: onHoverOut,
    onClick,
  };

  group.userData.cleanup = () => {
    hoverTl?.kill();
    pressTl?.kill();
    geometry.dispose();
    edgeGeo.dispose();
    material.dispose();
    edgeMat.dispose();
    colorMap.dispose();
    depthMap.dispose();
    if (valueText?.userData?.cleanup) valueText.userData.cleanup();
    if (labelText?.userData?.cleanup) labelText.userData.cleanup();
  };

  return group;
}
